contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public test function driving the minimal calls
    // params: initialDrugs seeds the market; recipient is the caller who will try getFreeKilo
    function runTest(uint256 initialDrugs, address recipient) public {
        // precondition: market must be empty before seeding
        require(c.marketDrugs() == 0);

        // seed the market (state-changing call)
        c.seedMarket(initialDrugs);

        // after seeding, on original P this sets initialized=true, so getFreeKilo should succeed for an account with 0 kilos
        // call getFreeKilo() as the recipient by using low-level call with abi encoding to simulate calling from this contract
        // but we must call through c's public interface; since we cannot change msg.sender for c.getFreeKilo(),
        // we instead check the observable effect: initialized() getter and then calling getFreeKilo for this contract's address

        // ensure contract reports initialized (this is the distinguishing observable)
        bool isInit = c.initialized();
        // require it's true to focus on the intended behavior; on mutant M this will be false and the assert below will fail
        require(isInit == true);

        // ensure this contract has zero kilos before calling
        require(c.getMyKilo() == 0);

        // now call getFreeKilo which should succeed (not revert) and set Kilos for msg.sender (this contract)
        c.getFreeKilo();

        // final assertion: after successful getFreeKilo, this contract's kilos must equal STARTING_KILOS
        assert(c.getMyKilo() == c.STARTING_KILOS());
    }

    // receive to accept any ether if needed by the caller
    receive() external payable {}
}

