pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzzed params: an address that will become CEO and an initial drugs amount
    function testFuzz_property(address potentialCeo, uint256 drugs) public {
        vm.assume(potentialCeo != address(0));
        // ensure the fuzzed drugs value is reasonable for gas but wide otherwise
        drugs = bound(drugs, 1, 1e30);

        // fund the potential CEO so they can call payable functions if needed
        vm.deal(potentialCeo, 1 ether);

        // 1) make the potentialCeo call DrugDealer() to set themselves as ceoAddress
        vm.prank(potentialCeo);
        // call the function; it is public and in original sets ceoAddress = msg.sender
        // record whether the call succeeded (should succeed on reference and mutant)
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        // require that the call did not revert (if it reverts, the property doesn't apply)
        vm.assume(ok);

        // 2) the new CEO seeds the market with some drugs by calling seedMarket
        vm.prank(potentialCeo);
        // seedMarket is payable but doesn't require ETH for this contract logic; send some value anyway
        c.seedMarket{value: 0}(drugs);

        // GENERAL RULE (single assertion): After the sequence where an address calls DrugDealer()
        // and then calls seedMarket(...), the contract's ceoAddress should equal that caller and
        // initialized must be true on the correct implementation. We observe the contract only
        // via public getters: ceoAddress() and initialized().
        // This is universally true on the reference but the mutant (which removed initialized assignment)
        // will for some inputs leave initialized == false here; the fuzzer can find such an input.
        assertTrue(c.ceoAddress() == potentialCeo && c.initialized() == true);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function runTest(uint256 drugs, uint256 seedEther) public {
        // ensure we can call seedMarket (marketDrugs must be zero)
        require(c.marketDrugs() == 0, "precondition: marketDrugs must be 0");

        // call seedMarket (may be payable); forward any Ether provided
        if (seedEther > 0) {
            require(address(this).balance >= seedEther, "Insufficient ETH for test");
            c.seedMarket{value: seedEther}(drugs);
        } else {
            c.seedMarket{value: 0}(drugs);
        }

        // After seeding, initialized must be true on the original contract
        assert(c.initialized() == true);
    }

    // allow this test contract to receive ETH for forwarding to c.seedMarket
    receive() external payable {}
}

