contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: caller provides an address to use as msg.sender for the call
    // and an amount of wei to fund this contract if needed (not used here). The test
    // must be executed by an EOA that is not necessarily the CEO; the rule checks that
    // invoking DrugDealer() does not let a non-CEO overwrite ceoAddress.
    function run(address caller) public {
        // read old CEO
        address oldCeo = c.ceoAddress();

        // require that the provided caller is different from oldCeo to create a distinguishing scenario
        require(caller != oldCeo, "caller must differ from current CEO");

        // Attempt to have caller invoke DrugDealer(): from this contract we cannot change msg.sender,
        // but we can simulate the security property by asserting that calling DrugDealer() now
        // cannot make ceoAddress equal to address(this) unless this contract already was the CEO.
        // So call DrugDealer() from this contract (msg.sender == address(this)).
        c.DrugDealer();

        // read new CEO
        address newCeo = c.ceoAddress();

        // Property: if address(this) was not the CEO before the call, it must not become the CEO after the call.
        // This captures that only the current CEO may set the CEO (the mutant allows anyone to set it).
        assert(!(oldCeo != address(this) && newCeo == address(this)));
    }

    // allow receiving ether if needed by external test harness
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to call DrugDealer from caller address `callerIsCEO` choice.
    // We express the call outcome by using low-level call to capture revert boolean.
    // We then assert that when callerIsCEO==true, the call succeeds and afterwards c.ceoAddress() == caller.

    // Note: because we cannot change msg.sender in this contract directly, we accept the caller's
    // address by having the external caller of test_logic be the candidate CEO. Thus the test
    // function must be called by the account that wants to act as msg.sender for c.DrugDealer.

    function test_logic() public {
        // Ensure c.ceoAddress() equals msg.sender to create the deciding state for the original contract.
        // This is a precondition: the property is about the behavior when the caller is the current CEO.
        require(c.ceoAddress() == msg.sender, "precondition: caller must be current CEO");

        // Prepare calldata for DrugDealer(): its selector is computed from signature "DrugDealer()".
        bytes memory payload = abi.encodeWithSignature("DrugDealer()");

        // Call c.DrugDealer() using this contract as msg.sender proxy: since we cannot forward msg.sender,
        // we call the function directly on c; in solidity the msg.sender will be this contract, not the external caller.
        // To make msg.sender for c be the external caller, the external caller must call this test function and then
        // make c.DrugDealer() themselves. But rules require we drive c only from this contract. To satisfy the rules while
        // making the deciding difference observable, we instead observe that when the external caller equals c.ceoAddress(),
        // calling c.DrugDealer() from this contract (whose address != c.ceoAddress()) will fail under original P (since only CEO can set),
        // but succeed under mutant M (which forbids CEO and allows non-CEO). To make a machine-checkable distinguishing property,
        // we therefore require the precondition that this contract is NOT the CEO and the external caller IS the CEO, then
        // check that a non-CEO caller (this contract) cannot successfully change ceoAddress to itself under P. The mutant would allow it.
    }

    // Because of the strict formatting constraints above, and the requirement that all state-changing calls to c be top-level,
    // we provide a single external function that performs the distinguishing sequence and ends with exactly one assert.
    // We implement it as a separate function that must be invoked by the external account equal to c.ceoAddress().

    function run_distinguishing_call() public {
        // Precondition: external caller (msg.sender) is the current CEO.
        require(c.ceoAddress() == msg.sender, "caller must be current CEO");
        // Also require that this contract is not the current CEO, so this contract's attempt to call DrugDealer represents a non-CEO caller.
        require(c.ceoAddress() != address(this), "test contract must not be CEO");

        // Now this contract (non-CEO) attempts to call DrugDealer on c.
        // We perform a low-level call so we can capture whether it reverted.
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));

        // After the call, observe the ceoAddress public getter and whether the low-level call succeeded.
        address newCeo = c.ceoAddress();

        // The distinguishing general rule: on original P, a non-CEO caller cannot become CEO by calling DrugDealer,
        // so either the call reverted (success==false) or ceoAddress did not change to this contract's address.
        // We assert the stronger deterministic condition that the call did NOT succeed in making this contract the CEO:
        // i.e., !(success == true && newCeo == address(this))).
        // Equivalently assert(success == false || newCeo != address(this)).
        assert(success == false || newCeo != address(this));
    }

    // Allow contract to receive Ether if needed by c functions (not used here but kept for completeness).
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Precondition: caller must be the current CEO according to the contract's public getter
        address currentCeo = c.ceoAddress();
        require(currentCeo == msg.sender, "caller must be current CEO");

        bool reverted; try c.DrugDealer() { reverted = false; } catch { reverted = true; }
        // General rule: if the caller equals the contract's ceoAddress, then DrugDealer must revert
        assert(reverted == true);
    }
