}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // call DrugDealer as the provided caller by using a low-level call via address(c)
        // We must invoke c.DrugDealer() from this contract but simulate caller via msg.sender cannot be changed here.
        // Instead we observe that behavior differs depending on whether caller equals c.ceoAddress() by performing two tries:
        // 1) If the provided caller equals c.ceoAddress(), then in original P the actual ceoAddress cannot call DrugDealer because only that address can set itself; but since we cannot change msg.sender, we check the relation between caller and c.ceoAddress and ensure the call reverts when caller != c.ceoAddress in original.
        // Directly call DrugDealer and record whether it reverts.
        try c.DrugDealer() { reverted = false; } catch { reverted = true; }
        // General rule: In the original contract, only the current CEO can successfully call DrugDealer to set ceoAddress to msg.sender.
        // This implies that when this contract's caller (run's caller) equals c.ceoAddress(), attempting to call DrugDealer from that caller would succeed; conversely, if caller != c.ceoAddress(), such a call would revert.
        // Since we cannot change msg.sender for c.DrugDealer here, we assert a logical relation between the provided `caller` parameter and the observed revert flag:
        // If `caller == c.ceoAddress()` then DrugDealer should NOT have reverted (reverted == false). Otherwise it should have reverted (reverted == true).
        assert((caller == c.ceoAddress() && reverted == false) || (caller != c.ceoAddress() && reverted == true));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require that c has been initialized with a ceoAddress that equals this caller OR not; we will observe revert behavior
        // We don't call any other functions; we only attempt DrugDealer and observe whether it reverts.
        bool reverted; try c.DrugDealer() { reverted = false; } catch { reverted = true; }
        // The rule: the call should succeed iff msg.sender equals c.ceoAddress()
        // We can observe c.ceoAddress() via its public getter.
        address ceo = c.ceoAddress();
        // If caller is the CEO, the original contract allows the call (no revert). If not, the call must revert.
        assert(reverted == (msg.sender != ceo));
    }
    receive() external payable { }
}
